1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: grid;
13	    place-items: center;
14	    background: #eef0f3;
15	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
16	  }
17	  .calc {
18	    width: min(320px, 100vw - 32px);
19	    padding: 16px;
20	    border-radius: 20px;
21	    background: #1f2329;
22	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
23	  }
24	  .display {
25	    height: 80px;
26	    margin-bottom: 16px;
27	    padding: 0 12px;
28	    border-radius: 12px;
29	    background: #111418;
30	    color: #fff;
31	    font-size: 40px;
32	    display: flex;
33	    align-items: center;
34	    justify-content: flex-end;
35	    overflow: hidden;
36	    white-space: nowrap;
37	    font-variant-numeric: tabular-nums;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 10px;
43	  }
44	  button {
45	    height: 60px;
46	    border: 0;
47	    border-radius: 12px;
48	    background: #3a4049;
49	    color: #fff;
50	    font: inherit;
51	    font-size: 22px;
52	    cursor: pointer;
53	  }
54	  button:hover { filter: brightness(1.15); }
55	  button:active { filter: brightness(0.9); }
56	  button:focus-visible { outline: 2px solid #8ab4ff; outline-offset: 2px; }
57	  .op { background: #f08c2e; }
58	  .op.active { background: #fff; color: #f08c2e; }
59	  .fn { background: #8a929c; color: #111; }
60	  .wide { grid-column: span 2; }
61	</style>
62	</head>
63	<body>
64	<main class="calc">
65	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
66	  <div class="keys">
67	    <button class="fn wide" data-testid="key-lparen" data-key="lparen" aria-label="open group">(</button>
68	    <button class="fn wide" data-testid="key-rparen" data-key="rparen" aria-label="close group">)</button>
69	    <button class="fn" data-testid="key-clear" data-key="clear">AC</button>
70	    <button class="fn" data-testid="key-sign" data-key="sign" aria-label="change sign">±</button>
71	    <button class="fn" data-testid="key-percent" data-key="percent" aria-label="percent">%</button>
72	    <button class="op" data-testid="key-div" data-key="div" aria-label="divide">÷</button>
73	    <button data-testid="key-7" data-key="7">7</button>
74	    <button data-testid="key-8" data-key="8">8</button>
75	    <button data-testid="key-9" data-key="9">9</button>
76	    <button class="op" data-testid="key-mul" data-key="mul" aria-label="multiply">×</button>
77	    <button class="op" data-testid="key-sub" data-key="sub" aria-label="subtract">−</button>
78	    <button data-testid="key-4" data-key="4">4</button>
79	    <button data-testid="key-5" data-key="5">5</button>
80	    <button data-testid="key-6" data-key="6">6</button>
81	    <button class="op" data-testid="key-add" data-key="add" aria-label="add">+</button>
82	    <button data-testid="key-1" data-key="1">1</button>
83	    <button data-testid="key-2" data-key="2">2</button>
84	    <button data-testid="key-3" data-key="3">3</button>
85	    <button class="wide" data-testid="key-0" data-key="0">0</button>
86	    <button data-testid="key-dot" data-key="dot" aria-label="decimal point">.</button>
87	    <button class="op" data-testid="key-equals" data-key="equals" aria-label="equals">=</button>
88	  </div>
89	</main>
90	<script>
91	// Pure calculator logic. State: acc (stored left operand), op (pending operator),
92	// entry (digits being typed, or null), value (the current number, never rounded),
93	// error (true after a division by zero; only clear leaves it), stack (saved acc/op of each
94	// open group), closed (true right after `)`: value is a finished group result, not an entry).
95	var OPS = {
96	  add: function (a, b) { return a + b; },
97	  sub: function (a, b) { return a - b; },
98	  mul: function (a, b) { return a * b; },
99	  div: function (a, b) { return a / b; }
100	};
101	
102	function initialState() {
103	  return { acc: null, op: null, entry: null, value: 0, error: false, stack: [], closed: false };
104	}
105	
106	function errorState(v) {
107	  return { acc: null, op: null, entry: null, value: v, error: true, stack: [], closed: false };
108	}
109	
110	function press(s, key) {
111	  if (key === 'clear') return initialState();
112	
113	  // In the error state every key except clear is ignored.
114	  if (s.error) return s;
115	
116	  if (/^[0-9]$/.test(key)) {
117	    var entry = s.entry === null || s.entry === '0' ? key : s.entry === '-0' ? '-' + key : s.entry + key;
118	    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry), error: false, stack: s.stack, closed: false };
119	  }
120	
121	  if (key === 'dot') {
122	    var e = s.entry === null ? '0' : s.entry;
123	    if (e.indexOf('.') !== -1) return s;
124	    e += '.';
125	    return { acc: s.acc, op: s.op, entry: e, value: Number(e), error: false, stack: s.stack, closed: false };
126	  }
127	
128	  // Sign and percent act on the current entry. Right after an operator there is no
129	  // entry yet, so they start one from 0. After a result or a closed group they act on the value.
130	  if (key === 'sign' || key === 'percent') {
131	    if (s.entry === null && (!s.op || s.closed)) {
132	      var nv = key === 'sign' ? -s.value : s.value / 100;
133	      return { acc: s.acc, op: s.op, entry: null, value: nv, error: false, stack: s.stack, closed: s.closed };
134	    }
135	    var cur = s.entry === null ? '0' : s.entry;
136	    var ne = key === 'sign' ? (cur[0] === '-' ? cur.slice(1) : '-' + cur) : shiftDecimal(cur, -2);
137	    return { acc: s.acc, op: s.op, entry: ne, value: Number(ne), error: false, stack: s.stack, closed: false };
138	  }
139	
140	  if (key in OPS) {
141	    // Operator right after another operator replaces it.
142	    if (s.op && s.entry === null && !s.closed) return { acc: s.acc, op: key, entry: null, value: s.value, error: false, stack: s.stack, closed: false };
143	    // Immediate execution: finish the waiting operation first, strictly left to right,
144	    // no precedence. The display always shows a real running result.
145	    var v = s.op ? OPS[s.op](s.acc, s.value) : s.value;
146	    if (!isFinite(v)) return errorState(v);
147	    return { acc: v, op: key, entry: null, value: v, error: false, stack: s.stack, closed: false };
148	  }
149	
150	  // `(` saves the waiting operation and starts a fresh one inside the group. It only
151	  // makes sense where a number could start, so it is ignored after an entry or a group.
152	  if (key === 'lparen') {
153	    if (s.entry !== null || s.closed) return s;
154	    var frame = { acc: s.acc, op: s.op };
155	    return { acc: null, op: null, entry: null, value: 0, error: false, stack: s.stack.concat([frame]), closed: false };
156	  }
157	
158	  // `)` finishes the group like equals, then restores the saved operation with the group
159	  // result as its right operand. Without an open group it is ignored.
160	  if (key === 'rparen') {
161	    if (!s.stack.length) return s;
162	    var g = s.op ? OPS[s.op](s.acc, s.value) : s.value;
163	    if (!isFinite(g)) return errorState(g);
164	    var top = s.stack[s.stack.length - 1];
165	    return { acc: top.acc, op: top.op, entry: null, value: g, error: false, stack: s.stack.slice(0, -1), closed: true };
166	  }
167	
168	  if (key === 'equals') {
169	    // Equals closes any groups left open.
170	    while (s.stack.length) {
171	      s = press(s, 'rparen');
172	      if (s.error) return s;
173	    }
174	    if (!s.op) return { acc: null, op: null, entry: null, value: s.value, error: false, stack: [], closed: false };
175	    var r = OPS[s.op](s.acc, s.value);
176	    if (!isFinite(r)) return errorState(r);
177	    return { acc: null, op: null, entry: null, value: r, error: false, stack: [], closed: false };
178	  }
179	
180	  return s;
181	}
182	
183	// Moves the decimal point of an entry string by n places, exactly, with no float noise.
184	// shiftDecimal('50', -2) is '0.5'.
185	function shiftDecimal(entry, n) {
186	  var sign = entry[0] === '-' ? '-' : '';
187	  var parts = entry.slice(sign.length).split('.');
188	  var digits = parts[0] + (parts[1] || '');
189	  var pos = parts[0].length + n;
190	  var str = pos <= 0 ? '0.' + '0'.repeat(-pos) + digits
191	    : pos >= digits.length ? digits + '0'.repeat(pos - digits.length)
192	    : digits.slice(0, pos) + '.' + digits.slice(pos);
193	  if (str.indexOf('.') !== -1) str = str.replace(/0+$/, '').replace(/\.$/, '');
194	  str = str.replace(/^0+(?=\d)/, '');
195	  return sign + str;
196	}
197	
198	// Presentation only: at most 10 significant digits, no trailing zeros, no separators.
199	// Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
200	function formatNumber(x) {
201	  var m = Math.abs(x).toExponential(9).split('e');
202	  var digits = m[0].replace('.', '');
203	  var exp = Number(m[1]);
204	  var sign = x < 0 ? '-' : '';
205	  if (x !== 0 && (exp >= 10 || exp < -9)) {
206	    return sign + m[0].replace(/\.?0+$/, '') + 'e' + m[1];
207	  }
208	  var int = exp >= 0 ? digits.slice(0, exp + 1) : '0';
209	  var frac = (exp >= 0 ? digits.slice(exp + 1) : '0'.repeat(-exp - 1) + digits).replace(/0+$/, '');
210	  return (int === '0' && frac === '' ? '' : sign) + int + (frac ? '.' + frac : '');
211	}
212	
213	// Visible text: the entry exactly as typed, Error, or the value formatted at render time.
214	function displayText(s) {
215	  if (s.error) return 'Error';
216	  if (s.entry !== null) return s.entry;
217	  return formatNumber(s.value);
218	}
219	
220	if (typeof document !== 'undefined') {
221	  var state = initialState();
222	  var display = document.querySelector('[data-testid="calc-display"]');
223	  var opButtons = document.querySelectorAll('[data-key="add"],[data-key="sub"],[data-key="mul"],[data-key="div"]');
224	
225	  function render() {
226	    display.textContent = displayText(state);
227	    display.setAttribute('data-value', String(state.value));
228	    display.setAttribute('data-error', state.error ? 'true' : 'false');
229	    for (var i = 0; i < opButtons.length; i++) {
230	      var b = opButtons[i];
231	      b.classList.toggle('active', state.op === b.dataset.key && state.entry === null && !state.closed);
232	    }
233	  }
234	
235	  document.querySelector('.keys').addEventListener('click', function (ev) {
236	    var btn = ev.target.closest('button');
237	    if (!btn) return;
238	    state = press(state, btn.dataset.key);
239	    render();
240	  });
241	
242	  var KEYMAP = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul', '/': 'div',
243	    '%': 'percent', '(': 'lparen', ')': 'rparen', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
244	  document.addEventListener('keydown', function (ev) {
245	    var key = /^[0-9]$/.test(ev.key) ? ev.key : KEYMAP[ev.key];
246	    if (!key || ev.ctrlKey || ev.metaKey || ev.altKey) return;
247	    ev.preventDefault();
248	    state = press(state, key);
249	    render();
250	  });
251	
252	  render();
253	}
254	</script>
255	</body>
256	</html>
